// ServerInterface represents all server handlers.
type ServerInterface interface {
	// DeleteAccount Delete the parent and everything that belongs to the family
	// (DELETE /account)
	DeleteAccount(w http.ResponseWriter, r *http.Request, params DeleteAccountParams)
	// GetAccount The parent's own profile
	// (GET /account)
	GetAccount(w http.ResponseWriter, r *http.Request, params GetAccountParams)
	// UpdateAccount Change name or language
	// (PATCH /account)
	UpdateAccount(w http.ResponseWriter, r *http.Request, params UpdateAccountParams)
	// ListDevices Known devices of the parent
	// (GET /account/devices)
	ListDevices(w http.ResponseWriter, r *http.Request)
	// RevokeDevice Forget a device (its cookie stops working)
	// (DELETE /account/devices/{deviceId})
	RevokeDevice(w http.ResponseWriter, r *http.Request, deviceId openapi_types.UUID)
	// ListPasskeys Passkeys of the parent
	// (GET /account/passkeys)
	ListPasskeys(w http.ResponseWriter, r *http.Request)
	// DeletePasskey Remove a passkey
	// (DELETE /account/passkeys/{passkeyId})
	DeletePasskey(w http.ResponseWriter, r *http.Request, passkeyId openapi_types.UUID)
	// RecordConsent Record the parent's consent to process a child's data
	// (POST /auth/consent)
	RecordConsent(w http.ResponseWriter, r *http.Request, params RecordConsentParams)
	// DeviceLogin Open the app on a known device without signing in
	// (POST /auth/device)
	DeviceLogin(w http.ResponseWriter, r *http.Request)
	// LoginParent Log a parent in
	// (POST /auth/login)
	LoginParent(w http.ResponseWriter, r *http.Request)
	// LogoutParent Revoke the parent's refresh token family
	// (POST /auth/logout)
	LogoutParent(w http.ResponseWriter, r *http.Request)
	// BeginPasskeyLogin Start a passkey sign in (discoverable credential, no username)
	// (POST /auth/passkeys/login/begin)
	BeginPasskeyLogin(w http.ResponseWriter, r *http.Request)
	// FinishPasskeyLogin Finish a passkey sign in
	// (POST /auth/passkeys/login/finish)
	FinishPasskeyLogin(w http.ResponseWriter, r *http.Request)
	// BeginPasskeyRegistration Start adding a passkey (WebAuthn creation options)
	// (POST /auth/passkeys/register/begin)
	BeginPasskeyRegistration(w http.ResponseWriter, r *http.Request)
	// FinishPasskeyRegistration Finish adding a passkey
	// (POST /auth/passkeys/register/finish)
	FinishPasskeyRegistration(w http.ResponseWriter, r *http.Request)
	// RefreshToken Exchange a refresh token for a new access token
	// (POST /auth/refresh)
	RefreshToken(w http.ResponseWriter, r *http.Request)
	// RegisterParent Create a parent account
	// (POST /auth/register)
	RegisterParent(w http.ResponseWriter, r *http.Request)
	// ListChildren List the parent's child profiles
	// (GET /children)
	ListChildren(w http.ResponseWriter, r *http.Request, params ListChildrenParams)
	// CreateChild Create a child profile
	// (POST /children)
	CreateChild(w http.ResponseWriter, r *http.Request, params CreateChildParams)
	// DeleteChild Delete a child profile and all of its data
	// (DELETE /children/{childId})
	DeleteChild(w http.ResponseWriter, r *http.Request, childId ChildId, params DeleteChildParams)
	// GetChild Get one child profile
	// (GET /children/{childId})
	GetChild(w http.ResponseWriter, r *http.Request, childId ChildId, params GetChildParams)
	// UpdateChild Update name, avatar or grade
	// (PATCH /children/{childId})
	UpdateChild(w http.ResponseWriter, r *http.Request, childId ChildId, params UpdateChildParams)
	// ListChallenges The challenge catalogue with this child's progress
	// (GET /children/{childId}/challenges)
	ListChallenges(w http.ResponseWriter, r *http.Request, childId ChildId, params ListChallengesParams)
	// AcceptChallenge The child accepts a challenge (progress starts counting now)
	// (POST /children/{childId}/challenges/{challengeId}/accept)
	AcceptChallenge(w http.ResponseWriter, r *http.Request, childId ChildId, challengeId string, params AcceptChallengeParams)
	// GetCollection Story cards earned by finishing chapters
	// (GET /children/{childId}/collection)
	GetCollection(w http.ResponseWriter, r *http.Request, childId ChildId, params GetCollectionParams)
	// GetEngagement Story-day streak and daily goal
	// (GET /children/{childId}/engagement)
	GetEngagement(w http.ResponseWriter, r *http.Request, childId ChildId, params GetEngagementParams)
	// ExportChildData Download all data held about a child (Law 25 access request)
	// (GET /children/{childId}/export)
	ExportChildData(w http.ResponseWriter, r *http.Request, childId ChildId, params ExportChildDataParams)
	// GetFeed The endless discovery feed (AI generated content, always labeled)
	// (GET /children/{childId}/feed)
	GetFeed(w http.ResponseWriter, r *http.Request, childId ChildId, params GetFeedParams)
	// AnswerFeedPuzzle Answer a puzzle from the feed
	// (POST /children/{childId}/feed/{itemId}/answer)
	AnswerFeedPuzzle(w http.ResponseWriter, r *http.Request, childId ChildId, itemId string, params AnswerFeedPuzzleParams)
	// ReactToFeedItem Like or save a feed item (private to the child, never shown to others)
	// (PUT /children/{childId}/feed/{itemId}/reaction)
	ReactToFeedItem(w http.ResponseWriter, r *http.Request, childId ChildId, itemId string, params ReactToFeedItemParams)
	// ClaimWelcomeGift Claim the one-time welcome gift (a card)
	// (POST /children/{childId}/gift/claim)
	ClaimWelcomeGift(w http.ResponseWriter, r *http.Request, childId ChildId, params ClaimWelcomeGiftParams)
	// GetGrowth The child compared with their own past (never with other children)
	// (GET /children/{childId}/growth)
	GetGrowth(w http.ResponseWriter, r *http.Request, childId ChildId, params GetGrowthParams)
	// GetHome Everything the child home feed needs in one request
	// (GET /children/{childId}/home)
	GetHome(w http.ResponseWriter, r *http.Request, childId ChildId, params GetHomeParams)
	// GetJourney The path of chapters for a child in one world
	// (GET /children/{childId}/journey)
	GetJourney(w http.ResponseWriter, r *http.Request, childId ChildId, params GetJourneyParams)
	// GetProgress Mastery per skill and active misconceptions
	// (GET /children/{childId}/progress)
	GetProgress(w http.ResponseWriter, r *http.Request, childId ChildId, params GetProgressParams)
	// GetDailyQuest Today's review quest, a chapter made of due reviews in a fresh story
	// (GET /children/{childId}/quests/daily)
	GetDailyQuest(w http.ResponseWriter, r *http.Request, childId ChildId, params GetDailyQuestParams)
	// GetReviewCalendar Upcoming spaced reviews
	// (GET /children/{childId}/reviews)
	GetReviewCalendar(w http.ResponseWriter, r *http.Request, childId ChildId, params GetReviewCalendarParams)
	// ListSessions Past sessions, newest first
	// (GET /children/{childId}/sessions)
	ListSessions(w http.ResponseWriter, r *http.Request, childId ChildId, params ListSessionsParams)
	// StartSession Start a chapter
	// (POST /children/{childId}/sessions)
	StartSession(w http.ResponseWriter, r *http.Request, childId ChildId, params StartSessionParams)
	// GetChildSettings Get a child's play settings
	// (GET /children/{childId}/settings)
	GetChildSettings(w http.ResponseWriter, r *http.Request, childId ChildId, params GetChildSettingsParams)
	// UpdateChildSettings Replace a child's play settings
	// (PUT /children/{childId}/settings)
	UpdateChildSettings(w http.ResponseWriter, r *http.Request, childId ChildId, params UpdateChildSettingsParams)
	// CreateChildToken Switch to a child (play mode)
	// (POST /children/{childId}/token)
	CreateChildToken(w http.ResponseWriter, r *http.Request, childId ChildId, params CreateChildTokenParams)
	// SendEvents Batch of privacy-safe UI events (no names, no free text)
	// (POST /events)
	SendEvents(w http.ResponseWriter, r *http.Request)
	// Health Liveness, with the narrator state
	// (GET /health)
	Health(w http.ResponseWriter, r *http.Request)
	// ListNotifications In-app notifications of the parent (BE-25)
	// (GET /notifications)
	ListNotifications(w http.ResponseWriter, r *http.Request, params ListNotificationsParams)
	// MarkNotificationRead Mark a notification as read
	// (POST /notifications/{notificationId}/read)
	MarkNotificationRead(w http.ResponseWriter, r *http.Request, notificationId string, params MarkNotificationReadParams)
	// GetPlatformPublic Public platform settings (unpaid policy, card threshold, trial length, feature flags)
	// (GET /platform/public)
	GetPlatformPublic(w http.ResponseWriter, r *http.Request, params GetPlatformPublicParams)
	// UnsubscribePush Remove a Web Push subscription (sign out, permission revoked, expired endpoint)
	// (DELETE /push/subscribe)
	UnsubscribePush(w http.ResponseWriter, r *http.Request)
	// SubscribePush Store the parent's Web Push subscription (VAPID)
	// (POST /push/subscribe)
	SubscribePush(w http.ResponseWriter, r *http.Request)
	// Ready Readiness (database, cache, engine, narrator)
	// (GET /ready)
	Ready(w http.ResponseWriter, r *http.Request)
	// GetWeeklyReport Weekly report for one child
	// (GET /reports/weekly)
	GetWeeklyReport(w http.ResponseWriter, r *http.Request, params GetWeeklyReportParams)
	// GetSession Session state (use it to resume after a reload)
	// (GET /sessions/{sessionId})
	GetSession(w http.ResponseWriter, r *http.Request, sessionId SessionId, params GetSessionParams)
	// NextBeat Get the next scene and question
	// (POST /sessions/{sessionId}/beats)
	NextBeat(w http.ResponseWriter, r *http.Request, sessionId SessionId, params NextBeatParams)
	// AnswerBeat Submit the child's answer
	// (POST /sessions/{sessionId}/beats/{beatId}/answer)
	AnswerBeat(w http.ResponseWriter, r *http.Request, sessionId SessionId, beatId BeatId, params AnswerBeatParams)
	// StreamNarration Stream the scene or the consequence as it is written
	// (GET /sessions/{sessionId}/beats/{beatId}/narration)
	StreamNarration(w http.ResponseWriter, r *http.Request, sessionId SessionId, beatId BeatId, params StreamNarrationParams)
	// FinishSession End the chapter early
	// (POST /sessions/{sessionId}/finish)
	FinishSession(w http.ResponseWriter, r *http.Request, sessionId SessionId, params FinishSessionParams)
	// PauseSession Pause (the child leaves; no penalty, no timer)
	// (POST /sessions/{sessionId}/pause)
	PauseSession(w http.ResponseWriter, r *http.Request, sessionId SessionId, params PauseSessionParams)
	// ResumeSession Resume a paused session
	// (POST /sessions/{sessionId}/resume)
	ResumeSession(w http.ResponseWriter, r *http.Request, sessionId SessionId, params ResumeSessionParams)
	// GetSessionSummary Parent recap of one session
	// (GET /sessions/{sessionId}/summary)
	GetSessionSummary(w http.ResponseWriter, r *http.Request, sessionId SessionId, params GetSessionSummaryParams)
	// ListSkills Curriculum skills (PDA), filterable
	// (GET /skills)
	ListSkills(w http.ResponseWriter, r *http.Request, params ListSkillsParams)
	// GetSubscription The parent's subscription (effective status and whether the family can play)
	// (GET /subscription)
	GetSubscription(w http.ResponseWriter, r *http.Request, params GetSubscriptionParams)
	// CancelSubscription Cancel at the end of the paid period (access continues until then)
	// (POST /subscription/cancel)
	CancelSubscription(w http.ResponseWriter, r *http.Request, params CancelSubscriptionParams)
	// CheckoutSubscription Start a paid plan (BE-24). The real backend returns the processor's hosted page URL; the mock completes instantly.
	// (POST /subscription/checkout)
	CheckoutSubscription(w http.ResponseWriter, r *http.Request, params CheckoutSubscriptionParams)
	// ListSubscriptionPlans Plans (CAD cents), bilingual features and payment methods
	// (GET /subscription/plans)
	ListSubscriptionPlans(w http.ResponseWriter, r *http.Request, params ListSubscriptionPlansParams)
	// ListWorlds The eight story worlds
	// (GET /worlds)
	ListWorlds(w http.ResponseWriter, r *http.Request, params ListWorldsParams)
}

